<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { Drill, DrillEvent } from '../domain/drill'
import DigitalTwinArena from './DigitalTwinArena.vue'
import AppIcon from './AppIcon.vue'
const props=defineProps<{drill:Drill;displayed:Drill;at:number;playing:boolean;busy:boolean;loading:boolean}>()
const emit=defineEmits<{back:[];seek:[at:number];play:[];fork:[at:number,sequence?:number];compare:[];export:[];assistant:[context?:{kind:'score'|'replay';id?:string;label:string;type?:string;detail?:string}]}>()
const selected=ref<string>(''), evidenceIndex=ref(0)
const root = ref<HTMLElement | null>(null)
const arena = ref<InstanceType<typeof DigitalTwinArena> | null>(null)
const indoorFloors=computed(()=>[...new Set(props.displayed.simulation.environment.indoor?.zones.filter(zone=>zone.floor>0).map(zone=>zone.floor)??[])].sort((a,b)=>a-b))
const indoorFloor=ref<number>()
watch(()=>props.drill.id,()=>{indoorFloor.value=undefined})
function reveal(section: 'events' | 'report' | 'branch' | 'focus', residentId?: string) {
  if (section === 'branch') selected.value = ''
  if (section === 'focus' && residentId) arena.value?.focusResident(residentId)
  const selector = section === 'branch' ? '.atlas-replay__events header button' : section === 'report' ? '.atlas-replay__evidence' : section === 'focus' ? '.atlas-replay__world' : '.atlas-replay__events'
  const target = root.value?.querySelector<HTMLElement>(selector)
  if (target) { target.tabIndex = -1; target.scrollIntoView({ block: 'nearest' }); target.focus({ preventScroll: true }) }
}
defineExpose({ reveal })
const events=computed(()=>[...props.drill.events].sort((a,b)=>a.sequence-b.sequence))
const score=computed(()=>props.drill.score??props.drill.score_preview)
const evidence=computed(()=>score.value.details[evidenceIndex.value])
function clock(n:number){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(Math.floor(n%60)).padStart(2,'0')}
function choose(event:DrillEvent){selected.value=event.id;emit('seek',event.elapsed_seconds)}
function fork(){const event=events.value.find(e=>e.id===selected.value);emit('fork',event?.elapsed_seconds??props.at,event?.sequence)}
function togglePlayback(){if(!props.playing&&props.at>=props.drill.elapsed_seconds)emit('seek',0);emit('play')}
</script>
<template>
 <section ref="root" class="atlas-replay" aria-label="演练复盘" data-ui-theme="immersive">
  <header class="atlas-replay__header"><button @click="emit('back')"><AppIcon name="back"/>返回现场</button><strong>智演安巷 <span>演练复盘</span></strong><small>{{ drill.status==='ended'?'现场已冻结':'历史过程只读，实时演练仍在运行' }}</small></header>
  <div class="atlas-replay__heading"><div><h1>{{drill.name}}</h1><p>演练时长 {{clock(drill.elapsed_seconds)}} · {{drill.simulation.summary.total}} 位居民 · {{events.length}} 条过程记录</p></div><div class="atlas-replay__score"><span>{{drill.score?'最终得分':'当前过程得分'}}</span><b>{{score.total_score}}</b><span>/ 100</span></div><div class="atlas-replay__heading-actions"><button @click="emit('assistant',{kind:'replay',label:'历史时刻 '+clock(at),type:'演练复盘',detail:'当前正在查看的只读历史快照'})"><AppIcon name="brain"/>AI 解读 {{clock(at)}}</button><button :disabled="!drill.score||busy" @click="emit('export')"><AppIcon name="download"/>导出复盘报告</button></div></div>
  <div class="atlas-replay__grid">
   <aside class="atlas-replay__events"><header><h2>关键决策 <small>{{events.length}}</small></h2><button :disabled="busy" @click="fork"><AppIcon name="split"/>创建决策分支</button></header><ol><li v-for="(event,index) in events" :key="event.id"><button :aria-pressed="selected===event.id" @click="choose(event)"><span class="atlas-replay__number">{{String(index+1).padStart(2,'0')}}</span><div><time>{{clock(event.elapsed_seconds)}}</time><strong>{{event.message}}</strong><small>{{event.actor}}</small></div></button></li></ol><p v-if="!events.length">本场尚无过程记录。</p></aside>
   <div class="atlas-replay__world"><nav aria-label="复盘世界"><span>历史现场 · {{clock(at)}}</span><button :disabled="busy" @click="fork">创建可操作分支</button><button :disabled="busy" @click="emit('compare')">双世界比较</button><label v-if="indoorFloors.length">观察楼层<select aria-label="复盘楼层" :value="indoorFloor??displayed.simulation.environment.indoor?.zones.find(zone=>zone.id===displayed.simulation.environment.indoor?.source_zone_id)?.floor" @change="indoorFloor=Number(($event.target as HTMLSelectElement).value);arena?.focusIndoorFloor(indoorFloor)"><option v-for="floor in indoorFloors" :key="floor" :value="floor">{{floor}} 层</option></select></label></nav><DigitalTwinArena ref="arena" :key="drill.id" status="paused" :elapsed-seconds="displayed.elapsed_seconds" :robot="displayed.robot" :simulation="displayed.simulation" :events="displayed.events" compact :high-contrast="false"/><footer><div><h2>原决策 <small>当前回放 {{clock(at)}}</small></h2><p>到达集合点 <strong>{{displayed.simulation.summary.evacuated}}</strong> / {{displayed.simulation.summary.total}} 人</p></div><div><p>烟气暴露 {{displayed.simulation.summary.smoke_exposed??0}} 人</p><p>拥堵 {{displayed.simulation.summary.congested??0}} 人 · 失联 {{displayed.simulation.summary.missing}} 人</p></div></footer></div>
   <aside class="atlas-replay__evidence"><header><h2>{{drill.score?'全场最终评分证据':'当前过程评分证据'}}</h2><div><button aria-label="上一条评分证据" :disabled="evidenceIndex===0" @click="evidenceIndex--"><AppIcon name="back"/></button><button aria-label="下一条评分证据" :disabled="evidenceIndex>=score.details.length-1" @click="evidenceIndex++"><AppIcon name="arrowRight"/></button></div></header><template v-if="evidence"><h3>{{evidence.name}} <b>{{evidence.score}} / {{evidence.max_score??'—'}}</b></h3><div class="atlas-replay__rule"><AppIcon name="tasks"/><h4>计分依据</h4><p>{{evidence.evidence}}</p><div class="atlas-replay__rule-actions"><button @click="emit('assistant',{kind:'score',id:evidence.name,label:evidence.name,type:'评分证据',detail:evidence.evidence})"><AppIcon name="brain"/>AI 解释这项得分</button><button v-if="evidence.at_seconds!==undefined" @click="emit('seek',evidence.at_seconds)">回看 {{clock(evidence.at_seconds)}} 相关事件</button></div></div></template><div class="atlas-replay__rule"><AppIcon name="users"/><h4>当前回放时刻的人员状态</h4><p>撤离中 {{displayed.simulation.summary.moving}} 人 · 尚未到达 {{displayed.simulation.summary.total-displayed.simulation.summary.evacuated}} 人</p></div><div class="atlas-replay__rule"><AppIcon name="help"/><h4>改进建议</h4><p v-for="recommendation in score.recommendations" :key="recommendation">{{recommendation}}</p><p v-if="!score.recommendations.length">暂无额外建议，请结合事件与人员轨迹检查处置过程。</p></div><small>证据来自本场仿真与操作记录，不是现场监控视频。</small></aside>
  </div>
  <footer class="atlas-replay__timeline"><label>事件时间线 <span>{{clock(at)}} / {{clock(drill.elapsed_seconds)}}</span><input aria-label="复盘时刻" type="range" min="0" :max="drill.elapsed_seconds" :value="at" @input="emit('seek',Number(($event.target as HTMLInputElement).value))"/></label><div><button :disabled="loading" aria-label="回到开始" @click="emit('seek',0)"><AppIcon name="back"/></button><button :disabled="!drill.elapsed_seconds" :aria-label="playing?'暂停复盘':'播放复盘'" @click="togglePlayback"><AppIcon :name="playing?'pause':'play'"/></button><button :disabled="loading" aria-label="向前十秒" @click="emit('seek',Math.min(drill.elapsed_seconds,at+10))"><AppIcon name="arrowRight"/></button><span>{{loading?'正在读取历史现场':'1.0 × · 历史快照'}}</span></div></footer>
 </section>
</template>
<style scoped>
