section.atlas-replay .atlas-replay__world>nav label { display:flex; align-items:center; gap:8px; font-size:16px; }
section.atlas-replay .atlas-replay__world>nav select { width:auto; min-height:44px; font:inherit; color:inherit; background:#123b2e; border:1px solid #547d65; border-radius:6px; padding:8px; }
section.atlas-replay .atlas-replay__world>nav button { min-height:44px; font-size:16px; }
