on{font-size:12px;padding:5px}.atlas-replay__events ol{padding:8px;margin:0;list-style:none}.atlas-replay__events li>button{width:100%;background:transparent;border-color:transparent;text-align:left;justify-content:flex-start;align-items:flex-start;gap:12px;padding:16px 8px}.atlas-replay__events li>button[aria-pressed=true]{border-color:#8bdfb5;background:#153c2e}.atlas-replay__number{border:1px solid #547d65;min-width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font-size:12px}.atlas-replay__events li div{display:grid;gap:10px}.atlas-replay__events time,.atlas-replay__events small{color:#b2c3b8;font-size:13px}.atlas-replay__events strong{font-size:14px;line-height:1.65}.atlas-replay__world{min-height:0;position:relative;display:flex;flex-direction:column;border:1px solid #345348;border-radius:7px;overflow:hidden}.atlas-replay__world>nav{position:absolute;top:14px;left:50%;transform:translateX(-50%);z-index:3;display:flex;align-items:center;border:1px solid #729b83;background:#09251c;border-radius:8px;overflow:hidden;white-space:nowrap}.atlas-replay__world>nav span{padding:12px 20px;color:#98efbb}.atlas-replay__world>nav button{border:0;background:transparent}.atlas-replay__world :deep(.twin-stage){flex:1;min-height:0;height:100%}.atlas-replay__world :deep(.twin-stage__viewport){height:100%;min-height:0}.atlas-replay__world>footer{display:flex;justify-content:space-between;padding:16px 20px;gap:20px;border-top:1px solid #37513e;background:#08281c}.atlas-replay__world footer p{font-size:13px;color:#b5cbbd}.atlas-replay__world footer strong{font-size:22px;color:#76deb0}.atlas-replay__evidence{padding:0 14px 14px}.atlas-replay__evidence>header{padding-inline:0}.atlas-replay__evidence>header>div{display:flex;gap:4px}.atlas-replay__evidence>header button{padding:5px;min-height:30px}.atlas-replay__evidence h3{display:flex;justify-content:space-between;gap:12px;font-size:16px;line-height:1.7}.atlas-replay__evidence h3 b{color:#e49b65;white-space:nowrap}.atlas-replay__rule{border:1px solid #365448;border-radius:6px;padding:14px;margin-bottom:14px}.atlas-replay__rule>svg{float:left;margin-right:8px;color:#90d8b1}.atlas-replay h4{margin:0 0 10px}.atlas-replay__rule p{line-height:1.85;color:#ccdbd1;margin:7px 0;font-size:14px}.atlas-replay__evidence>small{color:#a5baaf;font-size:13px}.atlas-replay__timeline{border:1px solid #2e5040;border-radius:7px;padding:14px 18px}.atlas-replay__timeline label{display:block;font-weight:600}.atlas-replay__timeline label span{font-weight:400;font-size:13px;margin-left:18px;color:#b5cabb}.atlas-replay__timeline input{display:block;width:100%;margin:16px 0 10px;accent-color:#76dba8;height:12px;min-height:12px;padding:0}.atlas-replay__timeline>div{display:flex;align-items:center;justify-content:center;gap:10px}.atlas-replay__timeline>div span{font-size:13px;color:#a8bead}@media(max-width:1100px){.atlas-replay__grid{grid-template-columns:210px minmax(0,1fr) 250px}.atlas-replay__events>header{flex-wrap:wrap}.atlas-replay__heading{gap:14px}.atlas-replay__heading h1{font-size:20px}.atlas-replay__heading-actions{flex-direction:column;align-items:stretch}.atlas-replay__header small{display:none}}@media(max-width:760px){.atlas-replay{overflow:auto;height:100dvh}.atlas-replay__grid{display:flex;flex-direction:column;flex:none}.atlas-replay__world{order:-1;height:420px}.atlas-replay__events{max-height:300px}.atlas-replay__heading{flex-wrap:wrap}.atlas-replay__heading>div:first-child{width:100%}.atlas-replay__score{margin-left:0}.atlas-replay__heading-actions{margin-left:auto;flex-direction:row;flex-wrap:wrap}.atlas-replay__heading-actions button{min-height:44px}.atlas-replay__header{gap:8px}.atlas-replay__header strong{font-size:16px}.atlas-replay__header strong span{margin-left:8px;padding-left:8px}}
